/// List the notes: Every note, newest first.
@MainActor
public enum NotesAction {
    public static let id = "notes"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (NotesInput) async throws -> NotesOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (NotesInput, Result<NotesOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: NotesInput) async throws -> NotesOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct NotesIntent: AppIntent {
    public static let title: LocalizedStringResource = "List the notes"
    public static let description = IntentDescription("List the notes. Read-only.")

    public init() {}

    public init(_ input: NotesInput) {
        self.init()
    }

    public var input: NotesInput {
        NotesInput()
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<NotesOutput, any Error>
        do { result = .success(try await NotesAction.run(input)) } catch { result = .failure(error) }
        if let dialog = NotesAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
