    public static var confirm: (@MainActor @Sendable (DeleteInput) async throws -> Void)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (DeleteInput, Result<DeleteOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: DeleteInput) async throws -> DeleteOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct DeleteIntent: AppIntent {
    public static let title: LocalizedStringResource = "Delete a note"
    public static let description = IntentDescription("Delete one note. A person says yes first.")

    @Parameter(title: "Note", description: "The note's id.")
    public var id: String

    public init() {}

    public init(_ input: DeleteInput) {
        self.init()
        self.id = input.id
    }

    public var input: DeleteInput {
        DeleteInput(id: id)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        // Consequential: the person says yes before it acts.
        if let confirm = DeleteAction.confirm { try await confirm(self.input) } else { try await requestConfirmation() }
        let input = self.input
        let result: Result<DeleteOutput, any Error>
        do { result = .success(try await DeleteAction.run(input)) } catch { result = .failure(error) }
        if let dialog = DeleteAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

